'use client'; 

import { useState } from 'react'; 

export default function Home() {
  const [complejidad, setComplejidad] = useState(50);
    const [tipoImagen, setTipoImagen] = useState('dossier');
      const [estadoImagen, setEstadoImagen] = useState('S E Q U E N C E _ W A I T I N G');
        const [estaCargando, setEstaCargando] = useState(false);
          const [saiActual, setSaiActual] = useState(0); 
            const [mostrarImagen, setMostrarImagen] = useState(false); 

              const manejarGeneracion = async () => {
                  setEstaCargando(true); 
                      setMostrarImagen(false); 
                          setEstadoImagen('I G N I T I O N . . . CONECTANDO MOTOR');

                              try {
                                    const respuesta = await fetch('/api/generar', {
                                            method: 'POST',
                                                    headers: { 'Content-Type': 'application/json' },
                                                            body: JSON.stringify({ tipo: tipoImagen, complejidad: complejidad }),
                                                                  });

                                                                        const datos = await respuesta.json();

                                                                              setEstadoImagen(datos.mensaje);
                                                                                    setSaiActual(datos.saiCalculado);
                                                                                          setMostrarImagen(true); 

                                                                                              } catch (error) {
                                                                                                    setEstadoImagen('E R R O R _ S Y S T E M _ H A L T E D');
                                                                                                          setMostrarImagen(false);
                                                                                                              } finally {
                                                                                                                    setEstaCargando(false); 
                                                                                                                        }
                                                                                                                          };

                                                                                                                            // NUEVA PALETA DE COLORES ESTRUCTURAL
                                                                                                                              const colores = {
                                                                                                                                  negroMate: '#121212',
                                                                                                                                      azulPetroleo: '#162a35',
                                                                                                                                          chartreuse: '#bfff00',
                                                                                                                                              cian: '#00e5ff',
                                                                                                                                                  blanco: '#ffffff',
                                                                                                                                                      amarillo: '#ffea00',
                                                                                                                                                          grisOscuro: '#333333',
                                                                                                                                                              textoGris: '#888888'
                                                                                                                                                                };

                                                                                                                                                                  return (
                                                                                                                                                                      <div style={{ 
                                                                                                                                                                            display: 'flex', 
                                                                                                                                                                                  flexDirection: 'column', 
                                                                                                                                                                                        minHeight: '100vh', 
                                                                                                                                                                                              backgroundColor: colores.negroMate, 
                                                                                                                                                                                                    color: colores.blanco, 
                                                                                                                                                                                                          // TIPOGRAFÍA DE PROTOCOLO (Pesada, cursiva y mayúsculas)
                                                                                                                                                                                                                fontFamily: '"Impact", "Arial Black", sans-serif',
                                                                                                                                                                                                                      fontStyle: 'italic',
                                                                                                                                                                                                                            textTransform: 'uppercase',
                                                                                                                                                                                                                                  letterSpacing: '1px'
                                                                                                                                                                                                                                      }}>

                                                                                                                                                                                                                                              {/* --- TOP BAR (AZUL PETRÓLEO) --- */}
                                                                                                                                                                                                                                                      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '15px 30px', backgroundColor: colores.azulPetroleo, borderBottom: `2px solid ${colores.negroMate}` }}>
                                                                                                                                                                                                                                                                  <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
                                                                                                                                                                                                                                                                                  <div style={{ backgroundColor: colores.cian, color: colores.negroMate, padding: '5px 10px', fontWeight: 'bold' }}>S.S</div>
                                                                                                                                                                                                                                                                                                  <h2 style={{ margin: 0, fontSize: '22px', letterSpacing: '2px' }}>SYNERGY STUDIO <span style={{ fontSize: '12px', color: colores.textoGris }}>V6.0</span></h2>
                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                          <div style={{ backgroundColor: colores.negroMate, border: `1px solid ${colores.cian}`, color: colores.cian, padding: '8px 20px', letterSpacing: '2px', fontSize: '14px' }}>
                                                                                                                                                                                                                                                                                                                                          {estaCargando ? 'OVERDRIVE ENGAGED ⚡' : 'SYSTEM STANDBY'}
                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                              </header>

                                                                                                                                                                                                                                                                                                                                                                      {/* --- CONTENEDOR PRINCIPAL --- */}
                                                                                                                                                                                                                                                                                                                                                                              <div style={{ display: 'flex', flex: 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                      {/* 1. BARRA LATERAL IZQUIERDA */}
                                                                                                                                                                                                                                                                                                                                                                                                                  {/* PRIMERA LÍNEA AMARILLA EN EL BORDE DERECHO */}
                                                                                                                                                                                                                                                                                                                                                                                                                              <nav style={{ width: '280px', padding: '30px 20px', backgroundColor: colores.negroMate, borderRight: `2px solid ${colores.amarillo}` }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                              <h3 style={{ color: colores.blanco, fontSize: '16px', marginBottom: '30px' }}>MANUFACTURING FEED</h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                              <ul style={{ listStyle: 'none', padding: 0, margin: 0, fontSize: '14px', letterSpacing: '1px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <li style={{ padding: '15px', backgroundColor: '#1a1a1a', borderLeft: `4px solid ${colores.cian}`, marginBottom: '10px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span style={{ color: colores.cian }}>●</span> SYSTEM_OPERATIONAL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <li style={{ padding: '15px', color: colores.textoGris }}>AUTHORITY LOOP</li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <li style={{ padding: '15px', color: colores.textoGris }}>THE INEVITABLE VERSION</li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <li style={{ padding: '15px', color: colores.textoGris }}>SYSTEM HANDOFF</li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </ul>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </nav>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* 2. VISOR CENTRAL (FONDO BLANCO) */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <main style={{ flex: 1, padding: '40px', display: 'flex', flexDirection: 'column', alignItems: 'center', backgroundColor: colores.blanco }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ width: '100%', maxWidth: '600px', height: '600px', backgroundColor: colores.blanco, border: `2px solid ${colores.grisOscuro}`, display: 'flex', alignItems: 'center', justifyContent: 'center', position: 'relative', overflow: 'hidden' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <span style={{ position: 'absolute', top: 10, left: 10, fontSize: '12px', color: colores.cian, zIndex: 10 }}>X: 00.00 <br/> Y: 00.00</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {mostrarImagen ? (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <img 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  src="/logo.jpg" 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              alt="Render Arquitectónico Generado" 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          style={{ width: '100%', height: '100%', objectFit: 'contain', backgroundColor: colores.blanco }} 
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) : (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Texto oscuro para que se vea sobre el fondo blanco
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <p style={{ color: estaCargando ? colores.cian : colores.negroMate, textAlign: 'center', padding: '20px', letterSpacing: '2px', fontSize: '18px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {estadoImagen}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </main>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* 3. PANEL DERECHO */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* SEGUNDA LÍNEA GRIS OSCURO EN EL BORDE IZQUIERDO */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <aside style={{ width: '350px', backgroundColor: colores.negroMate, padding: '30px', display: 'flex', flexDirection: 'column', gap: '30px', borderLeft: `2px solid ${colores.grisOscuro}` }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div style={{ borderBottom: `2px solid ${colores.grisOscuro}`, paddingBottom: '20px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <h1 style={{ fontSize: '90px', margin: '0', color: colores.chartreuse, lineHeight: '1' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {saiActual}<span style={{ fontSize: '40px' }}>%</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p style={{ margin: '10px 0 0 0', fontSize: '12px', color: colores.textoGris, letterSpacing: '2px' }}>N I V E L _ I N T E G R I D A D</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <label style={{ fontSize: '12px', color: colores.textoGris, letterSpacing: '1px' }}>PROTOCOL OUT:</label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <select value={tipoImagen} onChange={(e) => setTipoImagen(e.target.value)} style={{ width: '100%', padding: '12px', marginTop: '10px', backgroundColor: colores.negroMate, color: colores.blanco, border: `2px solid ${colores.grisOscuro}`, fontFamily: 'inherit', outline: 'none' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <option value="dossier">PORTADA DOSSIER MAESTRO</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <option value="nodo">NODO CONSTRUCTIVO</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <option value="banner">HERO BANNER</option>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </select>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <label style={{ fontSize: '12px', color: colores.textoGris, letterSpacing: '1px', display: 'flex', justifyContent: 'space-between' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <span>COMPLEXITY_GEOM:</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <span style={{ color: colores.cian }}>{complejidad}</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </label>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <input type="range" min="1" max="100" value={complejidad} onChange={(e) => setComplejidad(Number(e.target.value))} style={{ width: '100%', marginTop: '15px' }} />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div style={{ marginTop: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button style={{ width: '100%', padding: '15px', backgroundColor: colores.negroMate, color: colores.cian, border: `2px solid ${colores.cian}`, fontFamily: 'inherit', fontSize: '16px', letterSpacing: '2px', cursor: 'pointer' }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              EXPORTAR EXCEL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* BOTÓN VERDE CHARTREUSE */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button onClick={manejarGeneracion} disabled={estaCargando} style={{ width: '100%', padding: '15px', backgroundColor: colores.chartreuse, color: colores.negroMate, border: 'none', fontFamily: 'inherit', fontSize: '18px', letterSpacing: '1px', cursor: estaCargando ? 'not-allowed' : 'pointer', opacity: estaCargando ? 0.7 : 1 }}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {estaCargando ? 'P R O C E S A N D O . . .' : 'EXPORTAR EXPEDIENTE'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </aside>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }